import Foundation

/// Where a restore plan came from; printed at the top of every generated file.
public struct RestoreSource: Sendable {
    public var snapshotLabel: String?
    public var snapshotDate: Date
    public var generatedAt: Date
    /// "this Mac", "new-mac.json", or "an empty Mac".
    public var comparedAgainst: String

    public init(snapshotLabel: String?, snapshotDate: Date, generatedAt: Date = Date(), comparedAgainst: String) {
        self.snapshotLabel = snapshotLabel
        self.snapshotDate = snapshotDate
        self.generatedAt = generatedAt
        self.comparedAgainst = comparedAgainst
    }

    var snapshotDescription: String {
        let date = Self.day(snapshotDate)
        return snapshotLabel.map { "\"\($0)\" (\(date))" } ?? "snapshot from \(date)"
    }

    static func day(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }
}

// MARK: - Brewfile

/// Renders the Homebrew part of a plan as a `brew bundle` Brewfile.
public enum BrewfileExporter {
    public static func render(_ plan: RestorePlan, source: RestoreSource) -> String {
        var lines = [
            "# Brewfile generated by macblueprint \(MacBlueprint.version) on \(RestoreSource.day(source.generatedAt))",
            "# From \(source.snapshotDescription), compared against \(source.comparedAgainst).",
            "# Install with: brew bundle --file=Brewfile   (restore.sh does this for you)",
            "",
        ]
        if !plan.taps.isEmpty {
            lines += plan.taps.map { "tap \(ruby($0))" } + [""]
        }
        if !plan.formulae.isEmpty {
            lines += plan.formulae.map { "brew \(ruby($0))" } + [""]
        }
        if !plan.casks.isEmpty {
            lines += plan.casks.map { cask in
                "cask \(ruby(cask.token))" + (cask.note.map { "  # \($0)" } ?? "")
            } + [""]
        }
        if !plan.appStoreApps.isEmpty {
            lines += plan.appStoreApps.map { "mas \(ruby($0.name)), id: \($0.id)" } + [""]
        }
        return lines.joined(separator: "\n")
    }

    /// A Ruby double-quoted string literal.
    static func ruby(_ value: String) -> String {
        let escaped = value
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")
            .replacingOccurrences(of: "#", with: "\\#")
        return "\"\(escaped)\""
    }
}

// MARK: - restore.sh

/// Renders a plan as a bash script that installs only what can be automated.
///
/// The script shows a summary and asks before changing anything, supports
/// `--dry-run`, keeps going when a single step fails, and never installs
/// Homebrew itself (that stays a deliberate choice of the user).
public enum ScriptExporter {
    public static func render(_ plan: RestorePlan, source: RestoreSource) -> String {
        var s: [String] = []
        s.append("""
        #!/usr/bin/env bash
        # restore.sh, generated by macblueprint \(MacBlueprint.version) on \(RestoreSource.day(source.generatedAt))
        # From \(source.snapshotDescription), compared against \(source.comparedAgainst).
        #
        # Read PLAN.md and this file before running it.
        #   ./restore.sh --dry-run   show every command, change nothing
        #   ./restore.sh             show a summary, ask once, then install
        #   ./restore.sh --yes       install without asking
        set -euo pipefail

        DRY_RUN=0
        ASSUME_YES=0
        for arg in "$@"; do
          case "$arg" in
            -n|--dry-run) DRY_RUN=1 ;;
            -y|--yes) ASSUME_YES=1 ;;
            -h|--help) sed -n '2,8p' "$0"; exit 0 ;;
            *) echo "Unknown option: $arg (try --help)" >&2; exit 2 ;;
          esac
        done

        cd "$(dirname "$0")"
        FAILURES=()

        section() { printf '\\n==> %s\\n' "$*"; }
        run() {
          if [[ $DRY_RUN -eq 1 ]]; then
            printf '    would run:'; printf ' %q' "$@"; printf '\\n'
            return 0
          fi
          printf '    $'; printf ' %q' "$@"; printf '\\n'
          if ! "$@"; then
            FAILURES+=("$*")
            printf '    ! that failed, continuing with the rest\\n' >&2
          fi
        }

        """)

        // Summary + confirmation
        var summary: [String] = []
        if plan.usesHomebrew {
            summary.append("Homebrew: \(plan.taps.count) taps, \(plan.formulae.count) formulae, \(plan.casks.count) casks")
        }
        if !plan.appStoreApps.isEmpty { summary.append("App Store: \(plan.appStoreApps.count) apps (via mas)") }
        if plan.extensionCount > 0 { summary.append("Editor extensions: \(plan.extensionCount)") }

        if summary.isEmpty {
            s.append("""
            echo "Nothing to install automatically. See PLAN.md for the remaining manual steps."
            exit 0
            """)
            return s.joined(separator: "\n") + "\n"
        }

        s.append("echo \"This will install:\"")
        s += summary.map { "echo \(shellQuote("  - " + $0))" }
        s.append("""

        if [[ $DRY_RUN -eq 0 && $ASSUME_YES -eq 0 ]]; then
          read -r -p "Continue? [y/N] " reply
          if [[ ! "$reply" =~ ^[Yy]$ ]]; then
            echo "Nothing was changed."
            exit 0
          fi
        fi
        """)

        if plan.usesHomebrew {
            s.append("""

            section "Homebrew"
            BREW="$(command -v brew || true)"
            for candidate in /opt/homebrew/bin/brew /usr/local/bin/brew; do
              if [[ -z "$BREW" && -x "$candidate" ]]; then BREW="$candidate"; fi
            done
            if [[ -z "$BREW" ]]; then
              if [[ $DRY_RUN -eq 1 ]]; then
                echo "    Homebrew is not installed yet; it is needed for this step."
                BREW=brew
              else
                echo "Homebrew is not installed. Install it from https://brew.sh, then run this script again." >&2
                exit 1
              fi
            fi
            run "$BREW" bundle --file=Brewfile
            """)
        }

        if !plan.extensions.isEmpty {
            s.append("""

            find_editor_cli() {
              local candidate
              for candidate in "$@"; do
                if [[ "$candidate" == /* ]]; then
                  if [[ -x "$candidate" ]]; then echo "$candidate"; return 0; fi
                elif command -v "$candidate" >/dev/null 2>&1; then
                  command -v "$candidate"; return 0
                fi
              done
              return 1
            }

            # install_extensions <editor name> <cli candidates...> -- <extension ids...>
            install_extensions() {
              local editor="$1"; shift
              local candidates=()
              while [[ "$1" != "--" ]]; do candidates+=("$1"); shift; done
              shift
              section "$editor extensions"
              local cli
              if ! cli="$(find_editor_cli "${candidates[@]}")"; then
                if [[ $DRY_RUN -eq 1 ]]; then
                  cli="${candidates[0]}"
                else
                  echo "    $editor is not installed, skipping its extensions. Install it and run this script again."
                  FAILURES+=("$editor extensions (editor not installed)")
                  return 0
                fi
              fi
              local ext
              for ext in "$@"; do run "$cli" --install-extension "$ext"; done
            }
            """)
            for inventory in plan.extensions {
                let args = [inventory.editor.displayName] + inventory.editor.cliCandidates + ["--"] + inventory.extensions.map(\.id)
                s.append("install_extensions " + args.map(shellQuote).joined(separator: " "))
            }
        }

        let manualCount = plan.manualApps.count + plan.manualSteps.count
        s.append("""

        section "Done"
        if [[ ${#FAILURES[@]} -gt 0 ]]; then
          echo "These steps failed (you can run the script again; finished steps are skipped):"
          printf '  - %s\\n' "${FAILURES[@]}"
        fi
        """)
        if manualCount > 0 {
            s.append("echo \(shellQuote("\(manualCount) thing(s) still need you: see the \"Needs you\" section of PLAN.md."))")
        }
        return s.joined(separator: "\n") + "\n"
    }

    /// Single-quotes a value for bash.
    static func shellQuote(_ value: String) -> String {
        "'" + value.replacingOccurrences(of: "'", with: "'\\''") + "'"
    }
}

// MARK: - PLAN.md

/// Renders a plan as a human-readable checklist.
public enum PlanExporter {
    public static func render(_ plan: RestorePlan, source: RestoreSource) -> String {
        var md: [String] = []
        md.append("# Restore plan")
        md.append("")
        md.append("From \(source.snapshotDescription), compared against \(source.comparedAgainst). Generated by macblueprint \(MacBlueprint.version) on \(RestoreSource.day(source.generatedAt)).")
        md.append("")

        if plan.isEmpty {
            md.append("Nothing is missing. This Mac already has everything in the snapshot.")
            return md.joined(separator: "\n") + "\n"
        }

        md.append("| | |")
        md.append("|---|---|")
        md.append("| Installed by `restore.sh` | \(plan.automatedCount) |")
        md.append("| Needs you | \(plan.manualApps.count + plan.manualSteps.count) |")
        md.append("")
        md.append("**Next steps:** read this file → `./restore.sh --dry-run` → `./restore.sh`")
        md.append("")

        if !plan.warnings.isEmpty {
            md.append("## Before you start")
            md.append("")
            md += plan.warnings.map { "- \($0)" }
            md.append("")
        }

        if plan.automatedCount > 0 {
            md.append("## Installed by restore.sh")
            md.append("")
            if !plan.taps.isEmpty {
                md.append("**Homebrew taps:** " + plan.taps.map { "`\($0)`" }.joined(separator: ", "))
                md.append("")
            }
            if !plan.formulae.isEmpty {
                md.append("**Homebrew formulae (\(plan.formulae.count))**")
                md.append("")
                md += plan.formulae.map { "- [ ] `\($0)`" }
                md.append("")
            }
            if !plan.casks.isEmpty {
                md.append("**Apps via Homebrew casks (\(plan.casks.count))**")
                md.append("")
                md += plan.casks.map { "- [ ] `\($0.token)`" + ($0.note.map { ": \($0)" } ?? "") }
                md.append("")
            }
            if !plan.appStoreApps.isEmpty {
                md.append("**App Store apps (\(plan.appStoreApps.count))**")
                md.append("")
                md += plan.appStoreApps.map { "- [ ] \($0.name) (id \($0.id))" }
                md.append("")
            }
            for inventory in plan.extensions {
                md.append("**\(inventory.editor.displayName) extensions (\(inventory.extensions.count))**")
                md.append("")
                md += inventory.extensions.map { "- [ ] `\($0.id)`" }
                md.append("")
            }
        }

        if !plan.manualApps.isEmpty || !plan.manualSteps.isEmpty {
            md.append("## Needs you")
            md.append("")
            if !plan.manualApps.isEmpty {
                md.append("**Apps to download yourself (\(plan.manualApps.count))**")
                md.append("")
                for app in plan.manualApps {
                    let details = [app.version.map { "v\($0)" }, app.bundleId.map { "`\($0)`" }].compactMap { $0 }.joined(separator: ", ")
                    md.append("- [ ] **\(app.name)**" + (details.isEmpty ? "" : " (\(details))") + ". \(app.hint)")
                }
                md.append("")
            }
            for step in plan.manualSteps {
                md.append("- [ ] **\(step.title)**")
                if let note = step.note { md.append("  \(note)") }
                if !step.commands.isEmpty {
                    md.append("  ```bash")
                    md += step.commands.map { "  \($0)" }
                    md.append("  ```")
                }
            }
            md.append("")
        }

        if !plan.versionChanges.isEmpty {
            md.append("<details><summary>Already installed, different version (\(plan.versionChanges.count))</summary>")
            md.append("")
            md += plan.versionChanges.map { "- \($0.name): \($0.from) → \($0.to)" }
            md.append("")
            md.append("</details>")
            md.append("")
        }

        md.append("---")
        md.append("Not restored: passwords, SSH keys, tokens and other credentials (by design), app settings and dotfiles (planned).")
        return md.joined(separator: "\n") + "\n"
    }
}

// MARK: - Writing the files

/// Writes `PLAN.md`, `Brewfile` and an executable `restore.sh` into a directory.
public enum RestoreFiles {
    public static let planFile = "PLAN.md"
    public static let brewfile = "Brewfile"
    public static let script = "restore.sh"

    @discardableResult
    public static func write(_ plan: RestorePlan, source: RestoreSource, to directory: URL) throws -> URL {
        let fileManager = FileManager.default
        try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
        try Data(PlanExporter.render(plan, source: source).utf8).write(to: directory.appendingPathComponent(planFile), options: .atomic)
        try Data(BrewfileExporter.render(plan, source: source).utf8).write(to: directory.appendingPathComponent(brewfile), options: .atomic)
        let scriptURL = directory.appendingPathComponent(script)
        try Data(ScriptExporter.render(plan, source: source).utf8).write(to: scriptURL, options: .atomic)
        try fileManager.setAttributes([.posixPermissions: 0o755], ofItemAtPath: scriptURL.path)
        return directory
    }
}
